import{d as x,C as t,o as u,c,j as a,a as s,E as r,a3 as g}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"道德经第六十一章","description":"以江海下流与牝静之象读大国为下，辨明大小国之取与强者的责任。","frontmatter":{"title":"道德经第六十一章","description":"以江海下流与牝静之象读大国为下，辨明大小国之取与强者的责任。","category":"guide","aliases":["道德经第六十一章","老子第六十一章","dao de jing chapter 61"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-61.md","filePath":"daoism/dao-de-jing/chapter-61.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-61.md"},_=x({...m,setup(p){const i=[{id:"lowland-and-confluence",label:"大国者下流",showLabel:!0,sentences:[["大国者",{text:"下流",glossary:"xialiu"},"，天",{text:"下",glossary:"xia"},"之",{text:"交",glossary:"jiao"},"，天",{text:"下",glossary:"xia"},"之",{text:"牝",glossary:"pin"},"。"]],note:["【白话】大国应像江海下游那样处在低处，成为天下归会的地方，像雌牝那样宁静而能容受。开头借自然形象说明大国的处世姿态。","【王弼注择要】「江海居大而处下，则百川流之。」天下之交下注「天下所归会也」，天下之牝下注「静而不求，物自归之也」。","【读法】下流是水流下方的汇聚处；交取归会义，与第六十章交相之义分开。牝在此取静与容受的譬喻，不将古代雌雄取象直接变成现代性别分工。"]},{id:"stillness-and-taking-the-lower-place",label:"牝常以静胜牡",showLabel:!0,sentences:[[{text:"牝",glossary:"pin"},"常以",{text:"静",glossary:"jing"},"胜",{text:"牡",glossary:"mu"},"，以",{text:"静",glossary:"jing"},"为",{text:"下",glossary:"xia"},"。"]],note:["【白话】雌牝常以宁静胜过雄牡，由于宁静而能自处于下。句子用静与躁的对照，继续说明不争求何以能使物归来。","【王弼注择要】「以其静，故能为下也。」注又说「以其静复能为下，故物归之也」，以静、下、归相贯通。","【读法】胜在这里连归附之势理解，不只说武力击败。静不是没有回应，而是减少躁动贪求；此为章内取象，不作为所有雌雄行为的普遍事实。"]},{id:"two-ways-of-gaining",label:"故大国以下小国，则取小国",showLabel:!0,sentences:[["故大国以",{text:"下",glossary:"xia"},"小国，则",{text:"取",glossary:"qu"},"小国；小国以",{text:"下",glossary:"xia"},"大国，则",{text:"取",glossary:"qu"},"大国。"]],note:["【白话】大国能在小国面前自处谦下，就能获得小国的归附；小国能在大国面前自处谦下，就能获得大国的接纳。两边的取，所得关系并不相同。","【王弼注择要】大国取小国下注「小国则附之」；小国取大国下注「大国纳之也」。这里依所据注分译附与纳。","【读法】以下在此不是现代数量界线，而是以自身处于下。取另列本章获得归附或接纳义，不沿用第四十八章取天下的治理义。"]},{id:"lowering-and-mutual-aims",label:"故或下以取，或下而取",showLabel:!0,sentences:[["故或",{text:"下",glossary:"xia"},"以",{text:"取",glossary:"qu"},"，或",{text:"下",glossary:"xia"},"而",{text:"取",glossary:"qu"},"。大国不过欲",{text:"兼畜",glossary:"jianxu"},"人，小国不过欲",{text:"入事",glossary:"rushi"},"人。"]],note:["【白话】所以，有的自处于下以获得归附，有的自处于下而获得接纳。大国所求，不过是兼养、容纳他人；小国所求，不过是进入大国的秩序而事奉它。","【王弼注择要】「言唯修卑下，然后乃各得其所。」注从双方修下解释各得，不仅是大国单方面求取。","【读法】兼畜读 jiān xù，入事是进入而事奉。这里保留古代大小国关系中的不对等，不把它直接描述成现代平等国际关系，也不把归附美化成无条件的善。"]},{id:"the-larger-bears-the-lower-place",label:"大者宜为下",showLabel:!0,sentences:[["夫两者各得其所欲，大者",{text:"宜",glossary:"yi"},"为",{text:"下",glossary:"xia"},"。"]],note:["【白话】要让两者各得所欲，尤其应由较大、较强的一方自处谦下。末句从双方修下，进一步提出对大者的要求。","【王弼注择要】「小国修下，自全而已。」注再说「大国修下，则天下归之」，说明大小国处下所及的范围不同。","【读法】宜是应当；大国有更大的容纳和影响能力，因而更须先降低争先与逼迫。现代相参可反省强者如何提供空间，不把谦下用成要求弱者独自忍让的训诫。"]}],o=[{id:"xialiu",term:"下流",sense:1},{id:"jiao",term:"交",sense:2},{id:"pin",term:"牝",sense:1},{id:"mu",term:"牡",sense:1},{id:"jing",term:"静",sense:1},{id:"xia",term:"下",sense:1},{id:"qu",term:"取",sense:2},{id:"jianxu",term:"兼畜",sense:1},{id:"rushi",term:"入事",sense:1},{id:"yi",term:"宜",sense:1}];return(b,e)=>{const n=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),c("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第六十一章",tabindex:"-1"},[s("道德经第六十一章 "),a("a",{class:"header-anchor",href:"#道德经第六十一章","aria-label":'Permalink to "道德经第六十一章"'},"​")],-1)),r(n,{title:"为什么两者各得所欲，仍要大者宜为下",summary:"本章以江海处下、雌牝守静为喻，说明大国如何成为归会之处，再比较大小国各自求取的方式，最后把为下的要求落在大者。王弼分别用小国附之、大国纳之解释两种取。",points:[{label:"先读",text:"下流是百川汇聚的低处，天下之交是归会，不按现代品行词理解。"},{label:"再辨",text:"大国之取与小国之取分别看附与纳，不把两种关系一概译成吞并。"},{label:"后看",text:"章末强调大者宜为下，不能把谦下的责任只交给弱小的一方。"}],hint:"牝读 pìn，牡读 mǔ；兼畜的畜读 xù，为兼养、容纳。下既有处低之象，也有自处谦下的动作。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),r(l,{sections:i,glossary:o}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"大国者下流，天下之交，天下之牝。",tone:"从汇聚处起读",guide:"江海处下而百川归之，接着才谈大小国如何相处。"},{text:"故大国以下小国，则取小国；小国以下大国，则取大国。",tone:"分别附与纳",guide:"按王注把两种取译清，不抹平各自的处境。"},{text:"夫两者各得其所欲，大者宜为下。",tone:"把要求落在大者",guide:"双方修下之后，末句仍强调强大者应主动为下。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),r(h,{items:o}),e[4]||(e[4]=g("",15))])}}});export{f as __pageData,_ as default};
